function spaceInvaders(canvasId) {
const canvas = document.getElementById(canvasId);
const ctx = canvas.getContext("2d");

const W = 500, H = 500;
canvas.width = W; canvas.height = H;

// Sprites
const playerWidth = 20, playerHeight = 20;
const invaderWidth = 20, invaderHeight = 20;
const bulletWidth = 5, bulletHeight = 10;
const explosionFrames = 8;
const explosionSize = 20;
let explosionImg;

// Audio
let pewSound, explosionSound;

// Game objects array
let gameObjects = [];

// Keyboard control state
const keys = {};
window.addEventListener("keydown", e => keys[e.code] = true);
window.addEventListener("keyup", e => keys[e.code] = false);

// Game state
let lives = 3; score = 0; level = 1; livesText; scoreText; scoreDisplay;
let paused = false; gameOver = false;

// Bullet class
class Bullet {
  constructor(x, y, xdir, ydir, size, color) {
    this.x = x; this.y = y;
    this.xdir = xdir; this.ydir = ydir;
    this.size = size;
    this.color = color;
  }
  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
  update() {
    this.y += this.ydir;
    this.x += this.xdir;
  }
}

// Player class
class Player {
  constructor(x, y, w, h, c) {
    this.x = x; this.y = y;
    this.w = w; this.h = h;
    this.c = c;
    this.v = 5;
  }
  draw() {
    ctx.fillStyle = this.c; ctx.fillRect(this.x, this.y, this.w, this.h);
  }
  update() {
    if (keys["ArrowLeft"]) this.x -= this.v;
    if (keys["ArrowRight"]) this.x += this.v;
    if (this.x < 0) this.x = 0;
    if (this.x + this.w > W) this.x = W - this.w;
  }
}

// Invader class
class Invader {
  constructor(x, y, w, h, c, speed) {
    this.x = x; this.y = y;
    this.w = w; this.h = h;
    this.c = c;
    this.speed = speed;
  }
  draw() {
    ctx.fillStyle = this.c; ctx.fillRect(this.x, this.y, this.w, this.h);
  }
  update() {
    this.x += this.speed;
    if (this.x + this.w > W || this.x < 0) {
      this.speed *= -1;
      this.y += invaderHeight + 10;
    }
  }
}

// Explosion class
class Explosion {
  constructor(x, y, frames, size, img) {
    this.x = x; this.y = y;
    this.frames = frames;
    this.size = size;
    this.img = img;
    this.frame = 0;
  }
  draw() {
    ctx.drawImage(
      this.img,
      this.frame * explosionSize, 0,
      explosionSize, explosionSize,
      this.x, this.y,
      this.size, this.size
    );
  }
  update() {
    this.frame += 1;
    if (this.frame === this.frames) gameObjects = gameObjects.filter(o => o instanceof Explosion && o !== this);
  }
}

// On canvas clicked event
canvas.addEventListener("click", e => {
  if (paused) {
    // Resume game
    paused = false;
    document.removeEventListener("click", this);
  }
  else if (gameOver) {
    // Restart game
    setup();
  }
});
canvas.addEventListener("mousemove", e => {
  const x = e.offsetX, y = e.offsetY;
  const player = gameObjects.find(o => o instanceof Player);
  player.x = x - player.w / 2;
  player.y = y - player.h / 2;
});
canvas.addEventListener("click", e => {
  const x = e.offsetX, y = e.offsetY;
  gameObjects.push(new Bullet(x, y, 0, -5, 5, "#fff"));
});
canvas.addEventListener("click", e => {
  const x = e.offsetX, y = e.offsetY;
  gameObjects.push(new Bullet(x, y, 0, -5, 5, "#fff"));
});

function initSprites() {
  explosionImg = new Image();
  explosionImg.src = "explosion.png";
}

function setup() {
  initSprites();

  document.body.style.overflow = "hidden";
  document.documentElement.style.overflow = "hidden";
  document.body.style.cursor = "none";

  gameObjects = [];

  const player = new Player(W / 2, H - playerHeight * 2, playerWidth, playerHeight, "#fff");
  gameObjects.push(player);

  let x = (W - invaderWidth * 10) / 2;
  for (let y = 50; y < H - 50; y += invaderHeight * 2 + invaderHeight / 2) {
    for (let i = 0; i < 11; i++) {
      gameObjects.push(new Invader(x, y, invaderWidth, invaderHeight, "#fff", Math.random() < 0.5 ? -2 : 2));
      x += invaderWidth * 2 + invaderWidth / 2;
    }
    x = (W - invaderWidth * 10) / 2;
  }

  lives = 3; score = 0; level = 1;
  paused = false; gameOver = false;

  livesText = document.createElement("div");
  livesText.innerText = `Lives: ${lives}`;
  document.body.appendChild(livesText);

  scoreText = document.createElement("div");
  scoreText.innerText = `Score: ${score}`;
  document.body.appendChild(scoreText);
}

// Game loop
function loop() {
  if (paused) return;
  ctx.clearRect(0, 0, W, H);

  // Update gameobjects
  for (let i = gameObjects.length - 1; i >= 0; i--) {
    const obj = gameObjects[i];
    if (obj instanceof Player) {
      obj.update();
      if (obj.y > H) {
        lives--;
        livesText.innerText = `Lives: ${lives}`;
        setup();
        break;
      }
    } else if (obj instanceof Invader) {
      obj.update();
      if (obj.y > H) {
        gameOver = true;
        break;
      }
    } else if (obj instanceof Bullet) {
      obj.update();
      if (obj.y < 0) gameObjects = gameObjects.filter(b => b !== obj);
    }
    // Check collision with player
    if (!gameOver && (obj instanceof Bullet || obj instanceof Invader) && obj.x >= obj.x && obj.x + obj.w <= obj.x && obj.y >= obj.y && obj.y + obj.h <= obj.y) {
      if (obj instanceof Bullet) score++;
      else {
        gameObjects = gameObjects.filter(b => b !== obj);
        gameObjects.push(new Explosion(obj.x, obj.y, explosionFrames, explosionSize, explosionImg));
      }
      if (score % 500 === 0) level++;
      scoreText.innerText = `Score: ${score}`;
      if (obj instanceof Invader && gameObjects.every(o => o instanceof Invader && o.y !== H)) {
        setup();
        break;
      }
    }
  }
  // Draw gameobjects
  for (const obj of gameObjects) obj.draw();

  if (gameOver) {
    document.body.style.cursor = "auto";
    scoreDisplay = document.createElement("div");
    scoreDisplay.innerText = `GAME OVER! Your score was ${score}. Click to restart.`;
    document.body.appendChild(scoreDisplay);
  }

  requestAnimationFrame(loop);
}

setup();
loop();
}
const game = spaceInvaders("canvas");
